import{_ as s,o as n,c as p,a2 as e}from"./chunks/framework.RycU2wFZ.js";const k=JSON.parse('{"title":"支付状态机、幂等与故障恢复","description":"","frontmatter":{},"headers":[],"relativePath":"zh/learn/02-agent-payments/payment-state-and-idempotency.md","filePath":"zh/learn/02-agent-payments/payment-state-and-idempotency.md","lastUpdated":1792545482000}'),i={name:"zh/learn/02-agent-payments/payment-state-and-idempotency.md"};function t(l,a,h,c,d,o){return n(),p("div",null,[...a[0]||(a[0]=[e(`<h1 id="支付状态机、幂等与故障恢复" tabindex="-1">支付状态机、幂等与故障恢复 <a class="header-anchor" href="#支付状态机、幂等与故障恢复" aria-label="Permalink to &quot;支付状态机、幂等与故障恢复&quot;">​</a></h1><h2 id="一、为什么支付系统不能只记录成功和失败" tabindex="-1">一、为什么支付系统不能只记录成功和失败？ <a class="header-anchor" href="#一、为什么支付系统不能只记录成功和失败" aria-label="Permalink to &quot;一、为什么支付系统不能只记录成功和失败？&quot;">​</a></h2><p>假设 Agent 购买一份数据，支付金额为 0.10 USDC。</p><p>客户端发送支付请求后，网络突然中断。</p><p>此时系统知道的事实只有：</p><blockquote><p>我没有收到完整响应。</p></blockquote><p>但它并不知道：</p><ul><li>请求是否到达了服务端。</li><li>支付是否已经被验证。</li><li>交易是否已经提交。</li><li>交易是否已经确认。</li><li>数据是否已经交付。</li></ul><p>如果数据库只有一个字段：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>status = SUCCESS / FAILED</span></span></code></pre></div><p>就无法准确表示这些中间状态。</p><p>因此，支付系统需要使用状态机管理业务进度。</p><h2 id="二、什么是状态机" tabindex="-1">二、什么是状态机？ <a class="header-anchor" href="#二、什么是状态机" aria-label="Permalink to &quot;二、什么是状态机？&quot;">​</a></h2><p>状态机（State Machine）是一种用明确状态和允许的状态转换来管理流程的方法。</p><p>例如，一个支付请求可以经历：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CREATED</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>AUTHORIZED</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>VERIFIED</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>COMPLETED</span></span></code></pre></div><p>如果请求被拒绝，则可能进入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REJECTED</span></span></code></pre></div><p>如果请求过期，则可能进入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>EXPIRED</span></span></code></pre></div><p>这里的状态名称只是一个简化示例。实际系统必须明确定义每个状态的含义、进入条件、允许的后续状态以及失败处理方式。</p><p>状态机的价值在于：系统不会因为收到一个错误响应，就随意把状态改成任意值。</p><h2 id="三、agentpay-为什么要拆分三类状态" tabindex="-1">三、AgentPay 为什么要拆分三类状态？ <a class="header-anchor" href="#三、agentpay-为什么要拆分三类状态" aria-label="Permalink to &quot;三、AgentPay 为什么要拆分三类状态？&quot;">​</a></h2><p>AgentPay 的设计将支付意图、结算和服务交付分开管理。</p><h3 id="_1-payment-intent-支付意图" tabindex="-1">1. Payment Intent：支付意图 <a class="header-anchor" href="#_1-payment-intent-支付意图" aria-label="Permalink to &quot;1. Payment Intent：支付意图&quot;">​</a></h3><p>表示某个支付请求的业务生命周期。</p><p>示例状态：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CREATED</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>AUTHORIZED</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>VERIFIED</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>COMPLETED</span></span></code></pre></div><p>还可能存在：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REJECTED</span></span>
<span class="line"><span>EXPIRED</span></span>
<span class="line"><span>CANCELLED</span></span></code></pre></div><p>需要注意，<code>COMPLETED</code> 在实际实现中应有明确语义，不能含糊地同时表示“已经授权”“已经交付”和“已经结算”。</p><h3 id="_2-settlement-结算状态" tabindex="-1">2. Settlement：结算状态 <a class="header-anchor" href="#_2-settlement-结算状态" aria-label="Permalink to &quot;2. Settlement：结算状态&quot;">​</a></h3><p>记录资金结算的进展。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NOT_STARTED</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>SUBMITTED</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>PENDING</span></span>
<span class="line"><span>   ├── CONFIRMED</span></span>
<span class="line"><span>   ├── FAILED</span></span>
<span class="line"><span>   ├── REORGED</span></span>
<span class="line"><span>   └── UNKNOWN</span></span></code></pre></div><p>其中：</p><ul><li><code>SUBMITTED</code>：结算请求或交易已经提交。</li><li><code>PENDING</code>：结果仍在等待确认。</li><li><code>CONFIRMED</code>：达到系统定义的确认条件。</li><li><code>FAILED</code>：有充分证据表明结算失败。</li><li><code>REORGED</code>：已确认的交易受到链重组影响，需要重新核验。</li><li><code>UNKNOWN</code>：暂时无法确定结果。</li></ul><p>这些状态是 AgentPay 设计中的概念模型，实际状态转换应根据底层支付方案细化。</p><h3 id="_3-fulfillment-服务交付状态" tabindex="-1">3. Fulfillment：服务交付状态 <a class="header-anchor" href="#_3-fulfillment-服务交付状态" aria-label="Permalink to &quot;3. Fulfillment：服务交付状态&quot;">​</a></h3><p>记录购买的资源是否交付。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NOT_STARTED</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>PROCESSING</span></span>
<span class="line"><span>   ├── DELIVERED</span></span>
<span class="line"><span>   ├── FAILED</span></span>
<span class="line"><span>   └── RECOVERY_REQUIRED</span></span></code></pre></div><p>例如，数据已经查询成功并返回给客户端，可以标记为 <code>DELIVERED</code>。</p><p>如果支付流程已经进行，但上游 API 发生故障，就可能进入 <code>RECOVERY_REQUIRED</code>。</p><h2 id="四、为什么要把三类状态分开" tabindex="-1">四、为什么要把三类状态分开？ <a class="header-anchor" href="#四、为什么要把三类状态分开" aria-label="Permalink to &quot;四、为什么要把三类状态分开？&quot;">​</a></h2><p>考虑以下场景：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>支付授权成功</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>结算已经确认</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>上游数据服务超时</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Agent 没有拿到数据</span></span></code></pre></div><p>此时：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Payment Intent：已授权或已完成相关授权步骤</span></span>
<span class="line"><span>Settlement：已确认</span></span>
<span class="line"><span>Fulfillment：需要恢复</span></span></code></pre></div><p>如果系统把整个过程简单标记为 <code>FAILED</code>，就可能让重试逻辑误以为需要重新付款。</p><p>但实际上，资金可能已经成功转移。</p><p>正确做法是只恢复尚未完成的环节，而不是盲目重放整个支付流程。</p><h2 id="五、什么是幂等" tabindex="-1">五、什么是幂等？ <a class="header-anchor" href="#五、什么是幂等" aria-label="Permalink to &quot;五、什么是幂等？&quot;">​</a></h2><p>幂等（Idempotency）指在相同业务请求被重复提交时，系统能够避免重复产生不应该重复发生的业务效果。</p><p>例如，一个 Agent 发起支付请求：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>支付 0.10 USDC</span></span></code></pre></div><p>客户端等待超时后重新发送同一个业务请求。</p><p>如果系统没有幂等控制，就可能执行两次：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一次：支付 0.10 USDC</span></span>
<span class="line"><span>第二次：支付 0.10 USDC</span></span>
<span class="line"><span></span></span>
<span class="line"><span>总计：0.20 USDC</span></span></code></pre></div><p>如果两次请求本来代表同一笔业务，就产生了重复支付。</p><p>幂等机制的目标，是识别这两次请求属于同一个业务意图，并根据原请求的状态返回结果、继续处理或拒绝重复执行。</p><h2 id="六、什么是幂等键" tabindex="-1">六、什么是幂等键？ <a class="header-anchor" href="#六、什么是幂等键" aria-label="Permalink to &quot;六、什么是幂等键？&quot;">​</a></h2><p>幂等键（Idempotency Key）是用于标识一次业务请求的唯一标识。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tenant_id = tenant-001</span></span>
<span class="line"><span>agent_id = research-agent</span></span>
<span class="line"><span>payment_intent_id = intent-123</span></span></code></pre></div><p>可以为同一个支付意图生成稳定的幂等键。</p><p>一个简化的数据表设计如下：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> payment_intent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    tenant_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    idempotency_key </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    amount </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    updated_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    UNIQUE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (tenant_id, idempotency_key)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>这是一个用于讲解唯一约束的 SQLite 示例，尚不是完整的生产级支付表结构。</p><p>唯一约束可以阻止同一租户下出现重复的幂等键记录。</p><p>但是，<strong>数据库唯一约束本身不能保证链上只发生一次支付</strong>。</p><p>系统仍然需要把幂等记录、状态机、外部支付调用和恢复流程正确结合起来。</p><h2 id="七、为什么不能把每次-http-请求都当成一笔新支付" tabindex="-1">七、为什么不能把每次 HTTP 请求都当成一笔新支付？ <a class="header-anchor" href="#七、为什么不能把每次-http-请求都当成一笔新支付" aria-label="Permalink to &quot;七、为什么不能把每次 HTTP 请求都当成一笔新支付？&quot;">​</a></h2><p>假设 Agent 请求一个付费 API。</p><p>第一次请求超时后，HTTP 客户端自动重试。</p><p>如果每次 HTTP 请求都创建一个新的支付意图，系统就可能把同一笔业务拆成多个支付请求。</p><p>更合理的做法是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一次业务支付意图</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>稳定的 payment_intent_id</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>稳定的幂等键</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>允许多次安全查询或恢复</span></span></code></pre></div><p>重试时应复用同一个业务意图标识，而不是随意生成新的支付标识。</p><p>对于不同层次的重试，还应区分：</p><ul><li>查询原请求状态。</li><li>重试网络请求。</li><li>重试上游服务调用。</li><li>重新提交结算。</li><li>创建全新的支付请求。</li></ul><p>这些操作的风险和语义并不相同。</p><h2 id="八、支付结果未知时怎么办" tabindex="-1">八、支付结果未知时怎么办？ <a class="header-anchor" href="#八、支付结果未知时怎么办" aria-label="Permalink to &quot;八、支付结果未知时怎么办？&quot;">​</a></h2><p>这是最重要的故障恢复场景之一。</p><p>假设系统提交了一笔结算请求，然后网络超时。</p><p>错误处理：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求超时</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>直接认定失败</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>创建新支付</span></span></code></pre></div><p>更合理的处理方式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求超时</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>记录 UNKNOWN</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>保留原支付意图与幂等键</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>查询原请求状态</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>根据结果恢复</span></span></code></pre></div><p>如果原支付已经成功，系统就不应该再次发起一笔新的支付。</p><p>如果原支付尚未执行，需要根据底层服务的幂等能力和状态查询结果决定是否继续。</p><p>如果无法确认结果，则应保留未知状态，并采用明确的恢复或人工介入策略。</p><h2 id="九、预算预留与幂等如何配合" tabindex="-1">九、预算预留与幂等如何配合？ <a class="header-anchor" href="#九、预算预留与幂等如何配合" aria-label="Permalink to &quot;九、预算预留与幂等如何配合？&quot;">​</a></h2><p>假设 Agent 的预算为 1 USDC，申请支付 0.20 USDC。</p><p>系统首先为请求预留 0.20 USDC。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建支付意图</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>原子预留 0.20</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>执行支付</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>根据结果更新状态</span></span></code></pre></div><p>不同结果对应不同处理。</p><h3 id="场景-a-策略拒绝" tabindex="-1">场景 A：策略拒绝 <a class="header-anchor" href="#场景-a-策略拒绝" aria-label="Permalink to &quot;场景 A：策略拒绝&quot;">​</a></h3><p>支付没有进入执行阶段。</p><p>系统可以拒绝请求，并确保没有残留预算预留。</p><h3 id="场景-b-确认没有执行支付" tabindex="-1">场景 B：确认没有执行支付 <a class="header-anchor" href="#场景-b-确认没有执行支付" aria-label="Permalink to &quot;场景 B：确认没有执行支付&quot;">​</a></h3><p>在能够可靠确认未发生支付的前提下，可以按规则释放预留。</p><h3 id="场景-c-支付已确认成功" tabindex="-1">场景 C：支付已确认成功 <a class="header-anchor" href="#场景-c-支付已确认成功" aria-label="Permalink to &quot;场景 C：支付已确认成功&quot;">​</a></h3><p>系统将预留额度转换为已消耗额度。</p><h3 id="场景-d-支付结果未知" tabindex="-1">场景 D：支付结果未知 <a class="header-anchor" href="#场景-d-支付结果未知" aria-label="Permalink to &quot;场景 D：支付结果未知&quot;">​</a></h3><p>系统应保留足够的状态信息，避免因过早释放预算而重复授权新的消费。</p><p>这里的具体预算账务规则需要在实现中明确定义。</p><h2 id="十、恢复机制应该做什么" tabindex="-1">十、恢复机制应该做什么？ <a class="header-anchor" href="#十、恢复机制应该做什么" aria-label="Permalink to &quot;十、恢复机制应该做什么？&quot;">​</a></h2><p>一个 <code>reconcile()</code> 恢复流程可以定期或按需检查未完成的记录。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>扫描未完成的支付记录</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>读取当前状态</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>查询支付或结算结果</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>核对服务交付结果</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>执行允许的状态转换</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>更新数据库</span></span></code></pre></div><p>需要遵守几个原则：</p><ol><li>恢复过程必须可以重复执行。</li><li>不能把未知状态直接当成失败。</li><li>不能因为恢复任务重复运行就重复扣款。</li><li>状态转换必须经过校验。</li><li>无法自动判断的情况应保留记录并进入人工处理或专门恢复流程。</li></ol><h2 id="十一、agentpay-mvp-的最小实现范围" tabindex="-1">十一、AgentPay MVP 的最小实现范围 <a class="header-anchor" href="#十一、agentpay-mvp-的最小实现范围" aria-label="Permalink to &quot;十一、AgentPay MVP 的最小实现范围&quot;">​</a></h2><p>结合项目研发计划，MVP 需要重点完成：</p><ul><li>SQLite 持久化。</li><li>支付意图、结算和交付的独立状态管理。</li><li>状态转换守卫。</li><li>稳定的幂等键。</li><li>预算预留、提交和释放。</li><li>网络超时后的状态核验。</li><li>重复请求测试。</li><li>进程中途崩溃后的恢复测试。</li></ul><p>其中，故障注入测试非常重要。</p><p>例如，在不同执行阶段人为中断程序，检查重启后能否根据持久化状态继续处理，并验证不会因为重试产生重复结算。</p><h2 id="十二、小结" tabindex="-1">十二、小结 <a class="header-anchor" href="#十二、小结" aria-label="Permalink to &quot;十二、小结&quot;">​</a></h2><p>状态机负责管理支付流程走到了哪一步。</p><p>幂等负责识别重复业务请求。</p><p>恢复机制负责在超时、崩溃和外部服务故障后，安全地继续未完成的工作。</p><p>三者相互配合，才能降低重复扣款和状态错乱的风险。</p><p>需要牢记：</p><p><strong>网络超时不等于支付失败，支付成功不等于服务交付成功，重复请求也不应该自动变成新的支付。</strong></p><h2 id="下一篇" tabindex="-1">下一篇 <a class="header-anchor" href="#下一篇" aria-label="Permalink to &quot;下一篇&quot;">​</a></h2><p><a href="./payment-signatures">钱包与支付签名：EIP-712、EIP-3009</a></p>`,125)])])}const g=s(i,[["render",t]]);export{k as __pageData,g as default};
